function createVoiceRacingGame(canvasId){const canvas=document.getElementById(canvasId);if(!canvas)return;const ctx=canvas.getContext('2d');canvas.width=500;canvas.height=500;const startBtn=document.createElement('button');startBtn.textContent='Start Race';startBtn.style.position='absolute';startBtn.style.left=canvas.offsetLeft+'px';startBtn.style.top=(canvas.offsetTop+canvas.height+5)+'px';document.body.appendChild(startBtn);const muteBtn=document.createElement('button');muteBtn.textContent='Mute';muteBtn.style.position='absolute';muteBtn.style.left=(canvas.offsetLeft+80)+'px';muteBtn.style.top=(canvas.offsetTop+canvas.height+5)+'px';document.body.appendChild(muteBtn);let audioCtx=null, analyser=null, source=null, gainNode=null;let volume=0, muted=false;let running=false;let lastTime=0;let angle=0;const track={inner:150,outer:200,center:175};const lapsTotal=3;let lapCount=0;let lapStart=0;let bestLap=Infinity;let crash=false;let crashTimer=0;const obstacles=[{a:Math.PI*0.5,r:track.center-20},{a:Math.PI*1.3,r:track.center+20},{a:Math.PI*2.1,r:track.center-30}];function initAudio(){if(audioCtx)return;audioCtx=new (window.AudioContext||window.webkitAudioContext)();gainNode=audioCtx.createGain();analyser=audioCtx.createAnalyser();analyser.fftSize=512;source=audioCtx.createMediaStreamSource(stream);source.connect(gainNode).connect(analyser);gainNode.gain.value=1;}
let stream=null;function requestMic(){navigator.mediaDevices.getUserMedia({audio:true}).then(s=>{stream=s;initAudio();}).catch(()=>{alert('Microphone access denied.');});}
function getVolume(){if(!analyser)return 0;const data=new Uint8Array(analyser.frequencyBinCount);analyser.getByteTimeDomainData(data);let sum=0;for(let i=0;i<data.length;i++){let v=data[i]/128-1;sum+=v*v;}return Math.sqrt(sum/data.length);}function drawTrack(){ctx.strokeStyle='#555';ctx.lineWidth=20;ctx.beginPath();ctx.arc(250,250,track.inner,0,Math.PI*2);ctx.stroke();ctx.beginPath();ctx.arc(250,250,track.outer,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#999';ctx.lineWidth=2;ctx.beginPath();ctx.arc(250,250,track.center,0,Math.PI*2);ctx.stroke();}
function drawObstacles(){ctx.fillStyle='brown';obstacles.forEach(o=>{const x=250+o.r*Math.cos(o.a);const y=250+o.r*Math.sin(o.a);ctx.beginPath();ctx.arc(x,y,10,0,Math.PI*2);ctx.fill();});}
function drawCar(){const x=250+track.center*Math.cos(angle);const y=250+track.center*Math.sin(angle);ctx.save();ctx.translate(x,y);ctx.rotate(angle+Math.PI/2);ctx.fillStyle='red';ctx.fillRect(-10,-20,20,40);ctx.restore();}
function drawMeter(){ctx.fillStyle='gray';ctx.fillRect(10,470,100,20);ctx.fillStyle='lime';ctx.fillRect(10,470,volume*100,20);}
function drawInfo(){ctx.fillStyle='black';ctx.font='14px sans-serif';ctx.fillText('Lap: '+lapCount+'/'+lapsTotal,120,485);ctx.fillText('Best: '+(bestLap===Infinity?'--':(bestLap/1000).toFixed(2)+'s'),250,485);if(crash){ctx.fillStyle='orange';ctx.font='30px sans-serif';ctx.fillText('Crash!',200,250);}if(lapCount===lapsTotal){ctx.fillStyle='green';ctx.font='30px sans-serif';ctx.fillText('Race Complete!',130,250);}}
function update(dt){if(!running)return;volume=muted?0:getVolume();let speed=volume*2;if(crash){speed*=0.2;crashTimer-=dt;if(crashTimer<=0)crash=false;}angle+=speed*dt/100;if(angle>Math.PI*2)angle-=Math.PI*2;obstacles.forEach(o=>{const d=Math.abs(angle-o.a);if(d<0.05&&Math.abs(track.center-o.r)<15){crash=true;crashTimer=500;}});if(angle<0.02&&lastAngle>Math.PI*1.98){lapCount++;const now=performance.now();if(lapCount===1)lapStart=now;else{const lapTime=now-lapStart;if(lapTime<bestLap)bestLap=lapTime;lapStart=now;}if(lapCount>=lapsTotal)running=false;}}lastAngle=angle;}
function loop(ts){if(!lastTime)lastTime=ts;const dt=ts-lastTime;lastTime=ts;ctx.clearRect(0,0,canvas.width,canvas.height);drawTrack();drawObstacles();drawCar();drawMeter();drawInfo();update(dt);requestAnimationFrame(loop);}startBtn.onclick=()=>{if(running)return;requestMic();running=true;lapCount=0;bestLap=Infinity;crash=false;angle=0;lastAngle=0;lastTime=0;requestAnimationFrame(loop);};muteBtn.onclick=()=>{muted=!muted;muteBtn.textContent=muted?'Unmute':'Mute';if(gainNode)gainNode.gain.value=muted?0:1;};}
